      es: ["Mercancías coloridas", "Bullicio vibrante", "Intercambio cultural", "Descubrimiento para niños"],
      pt: ["Mercadorias coloridas", "Agitação vibrante", "Intercâmbio cultural", "Descoberta para crianças"],
